INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('torta-de-ricota', '= Torta de ricota =', 'Massas', '2009-12-08', 'Receita importada de 08_12_2009_torta_de_ricota.doc', '[]', NULL, '= Torta de ricota = receita passada no dia 08/12/2009 ingredientes Ricota fresca100%2500g Creme de confeiteiro20%500 g Açúcar 60%1500g Gema16%400g Uvas passas8%200 g Frutas Cristalizadas8%200g Canela em pó0,2%5g Clara 24%600g Essência de limãoQBQB fimIngredientes ''''''Modo de preparo'''''' Peneire a ricota e junte a todos os ingredientes menos as claras e bata na primeira velocidade e reserve. Bata as claras na terceira velocidade e vá adicionando lentamente o restante do ingredientes. ''''''Modo de montagem'''''' Abra a massa com uma espessura bem fina e forre a assadeira com a massa recheie, cubra e pincele com gema a superfície da torta e leve ao forno mais ou menos 25 minutos a uma temperatura de 200 graus .', '', 'https://images.unsplash.com/photo-1641848421644-a1603f016f51?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8dG9ydGElMjBkZSUyMHJpY290YXxlbnwwfHx8fDE3ODUxOTE0MTF8MA&ixlib=rb-4.1.0&q=80&w=400', 'torta de ricota');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('queijadinha', '= Queijadinha =', 'Paes', '2009-12-08', 'Receita importada de 08_12_2009_Queijadinha.doc', '[]', NULL, '= Queijadinha = receita passada no dia 08/12/2009 ingredientes Açúcar 100%500 g Margarina10%50g Ovos20%100g Água 50%250g Coco seco açucarado80%400g Gemas20%100g queijo parmesão100%500g fimIngredientes ''''''Modo de preparo.'''''' Coloque em uma panela , o açúcar, água e a margarina e leve ao fogo e deixe ferver, esfrie a mistura até que ela fique morna e adicione o restante dos ingredientes e espere o ponto. Forre as formas com papel antes de colocar a massa, e'''''' leve ao forno por mais ou menos 20 minutos'''''' ''''''a uma temperatura de 200 graus''''''. OBSERVAÇÃO! Se não usar formas de papel pode untar com manteiga e polvilhar com açúcar, e use geleia de brilho para acabamento.', '', 'https://images.unsplash.com/photo-1610638137223-cad2c38a8fd0?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8cXVlaWphZGluaGF8ZW58MHx8fHwxNzg1MTc1MTg0fDA&ixlib=rb-4.1.0&q=80&w=400', 'queijadinha');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('quindim-de-coco-fresco', 'Quindim de coco fresco', 'Paes', '2009-12-07', 'Receita importada de 07_12_2009_quindim_de_coco_fresco.doc', '{"gemas":"64% - 1600g","ac-ucar":"100% - 2500g","margarina":"12% - 300g","coco-fresco":"60% - 1500g"}', NULL, 'Junte o coco e o açúcar e misture manualmente e deixe descansar por 1 hora. Coloque a margarina em uma panela e leve ao forno para derreter  e tire do fogo e acrescentando as gemas o coco fresco ralado com açúcar  misture com as mãos. Coloque a massa em  formas undadas com margarina e polvilhadas com açúcar e leve ao forno por mais ou menos 20 minutos a um temperatura    de 200 graus em banho maria.', '', 'https://imgs.search.brave.com/-pEZ-O6L1FNb8P56GMw2lA9lF94oLrPSgaBHhtD_p54/rs:fit:500:0:1:0/g:ce/aHR0cHM6Ly93d3cu/cmVjZWl0YXNuZXN0/bGUuY29tLmJyL3Np/dGVzL2RlZmF1bHQv/ZmlsZXMvc3R5bGVz/L3JlY2lwZV9kZXRh/aWxfZGVza3RvcF9u/ZXcvcHVibGljL3Ny/aF9yZWNpcGVzLzJh/YjlkYTQ2NmQ5YzM0/MDRjOWZkNjk1NGM0/NzQ4NzdmLmpwZz9p/dG9rPVhLSERaQjA4', 'fresh grated');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('p-ao-integral', 'Pão Integral', 'Paes', '2009-12-07', 'Receita importada de 07_12_2009_pao_integral.doc', '{"gua":"58% - 1740g","sal":"2% - 60g","reforcador":"1% - 30g","fermento-fresco":"3% - 90g","farinha-de-trigo-especial":"50% - 1500g","farinha-de-trigo-integral":"50% - 1500g"}', NULL, 'Coloque na masseira todos os ingredientes secos deixe bater por 1 minuto, e em seguida coloque a água e deixe bater por mais 5 minutos, ou até ficar lisa e homogênea, após bater coloque a massa sobre uma mesa untada com óleo e corte a massa em pedaços de 500 gramas e enrole como se enrola rocambole   de deixe descansar para crescer em forma para pão de forma  até a borda da forma e leve ao forno por mais ou menos 30 minutos a uma temperatura de 200 graus com vapor. ', 'OBSERVAÇÃO ! Desenforme os pães assim  que tirar do forno !', 'https://images.unsplash.com/photo-1509440159596-0249088772ff?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8d2hvbGUlMjB3aGVhdCUyMGJyZWFkfGVufDB8fHx8MTc4NTE3NDg5Nnww&ixlib=rb-4.1.0&q=80&w=400', 'whole wheat bread');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('biscoito-agua-e-sal', 'Biscoito água e sal', 'Massas', '2009-12-02', 'Receita importada de 02_12_2009_biscoito_agua_e_sal.doc', '{"sal":"2% - 20g","ovos":"3% - 30g","açúcar":"2% - 20g","margarina":"3% - 30g","farinha-de-trigo":"100% - 1000g"}', NULL, 'Coloque na batedeira ou na masseira todos os produtos de deixe bater mais ou menos 5 minutos ou até obter uma massa lisa e homogênea.  Coloque a massa sobre uma mesa  levemente untada com óleo estique a massa e com um rolo e corte com um cortador redondo. Arrume em uma bandeja levemente untada dom óleo sobre o regime de arrumação de sua escolha e leve ao forno por mais ou menos 15 minutos a uma temperatura de 200 graus. ', 'OBESERVAÇÃO ! O biscoito de sair claro do forno !', 'https://images.unsplash.com/photo-1442604699113-7d805614c476?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8Y3JlYW0lMjBjcmFja2VyfGVufDB8fHx8MTc4NTE3NDI1MXww&ixlib=rb-4.1.0&q=80&w=400', 'cream cracker');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('massa-de-bomba', '= Massa de bomba =', 'Massas', '2009-11-30', 'Receita importada de 30_11_2009_Massa_de_bomba.doc', '[]', NULL, '= Massa de bomba = Receita passada no dia 30/11/2009 ingredientes Farinha de trigo100%600g Ovos167%1002g Margarina83%498g Água167%1002g Sal1%6g fimIngredientes ''''''Modo de preparo'''''' Coloque em uma panela margarina sal e água e deixe ferver mexendo com uma colher de pau, acrescente a farinha e deixe cozinhar, após leve para batedeira acrescentando os ovos lentamente. Use um ''''''saco ou manga de confeitar com bico 8B'''''' e modele em bandeja levemente untada com óleo com tamanho aproximado de 7 centímetros, e leve ao forno por ''''''mais ou menos ou menos 20 minutos'''''' a uma ''''''tempera 200 graus sem vapor.''''''', '', 'https://images.unsplash.com/photo-1729284045177-7a40238e4cd0?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8bWFzc2ElMjBkZSUyMGJvbWJhfGVufDB8fHx8MTc4NTE5MTQyMHww&ixlib=rb-4.1.0&q=80&w=400', 'massa de bomba');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('massa-flora', '= Massa Flora =', 'Paes', '2009-11-30', 'Receita importada de 30_11_2009_Massa_flora.doc', '[]', NULL, '= Massa Flora = Receita passada no dia 30/11/2009 ingredientes Farinha de trigo 100%1500g Açúcar33%495g Margarina67%1005g Gema10%150g Essência de limãoQBQB fimIngredientes ''''''Modo de preparo'''''' Coloque a farinha sobre a mesa e abra uma cova, e ponha o açúcar, a margarina e a essência de limão no meio, e misture com as mãos até formar uma massa lisa e homogênea (o aspecto da massa e semelhante ao da massa de coxinha). Arrume a massa em formas de empada com camadas finas de fure cada uma com um garfo e ''''''leve ao forno por mais ou menos 15 minutos ''''''a uma ''''''temperatura de 180° graus''''''.', '', 'https://picsum.photos/seed/massaflora/400/300', 'massa flora');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('bolo-de-fub-a', '= Bolo de fubá =', 'Bolos', '2009-11-30', 'Receita importada de 30_11_2009_bolo_de_fuba.doc', '[]', NULL, '= Bolo de fubá = receita passada no dia 30/11/2009 ingredientes Fubá100%900g Margarina33%297g Farinha de trigo24%216g Açúcar111%999g Ovos88%792g Leite133%1197g Fermento em pó quimico 6%54g Erva doce5%45g fimIngredientes ''''''Modo de Preparo'''''' Junte a margarina, açúcar, leite e a erva doce e leve ao fogo para ferver, e quando ferver junte o fubá e deixe cozinhar muito bem. Após coloque na batedeira e acescente os ovos de vagar e depois a farinha e o fermento e deixe bater na terceira velocidade até obter a massa no ponto certo. Coloque a massa em um tabuleiro untado com margarina e polvilhado com farinha, e leve ao forno por ''''''mais ou menos 25 minutos'''''' a uma ''''''temperatura de 200 graus. ''''''', '', 'https://picsum.photos/seed/bolodefub/400/300', 'bolo de fuba');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('biscoito-de-cebola-ou-queijo', '= Biscoito de cebola ou queijo =', 'Bolos', '2009-11-25', 'Receita importada de 25_11_2009_biscoito_de_cebola_ou_queijo.doc', '[]', NULL, '= Biscoito de cebola ou queijo = Receita passasda no dia 25/11/2009 ingredientes Farinha de trigo100%500g sal2%10g margarina60%300g gema6%30g queijo tipo parmesão ou cebola10%50g fimIngredientes ''''''Modo de preparo'''''' Coloque a farinha de trigo sobre uma mesa e abra uma cova e coloque os ingredientes e faça uma massa lisa e homogênea. Modele e coloque em tabuleiro sem untar e pinte com gema de ovo e polvilhe queijo ralado por cima. Leve ao forno ''''''mais ou menos por 10 minutos'''''' ou até dourar a uma ''''''temperatura de 170° graus''''''.', '', 'https://images.unsplash.com/photo-1598142982901-df6cec10ae35?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8YmlzY29pdG8lMjBkZSUyMGNlYm9sYSUyMG91JTIwcXVlaWpvfGVufDB8fHx8MTc4NTE5MTQxOXww&ixlib=rb-4.1.0&q=80&w=400', 'biscoito de cebola ou queijo');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('massa-folhada', '= Massa folhada  =', 'Paes', '2009-11-25', 'Receita importada de 25_11_2009_massa_folhada_escocesa.doc', '[]', NULL, '= Massa folhada  = (de processo escocesa) Receita passada no dia 25/11/2009 ingredientes Farinha de trigo100%1250g Margarina folhada80%1000g Água64%800g Sal2%25g fimIngredientes ''''''Modo de preparo'''''' Coloque a farinha sobre a mesa e faça uma cova e coloque o sal, Corte a margarina em cubinhos adicione a massa e misture muito bem com as mãos até formar uma massa lisa e homogênea . ''''''Estique a massa e dê 3 voltas de 3'''''' e depois mais ''''''quantas forem necessárias'''''' para a margarina se incorporar totalmente na massa, e deixe a massa ''''''descansar por 30 minutos'''''' coberta com um pano, modele e deixe ''''''descansar mais 30 minutos'''''', pinte com gemas de ovo e leve ao forno por mais ou menos 10 minutos a uma ''''''temperatura de 180 graus''''''.', '', 'https://images.unsplash.com/photo-1606854429271-dfe28e2627bd?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8bWFzc2ElMjBmb2xoYWRhfGVufDB8fHx8MTc4NTE5MTQyMHww&ixlib=rb-4.1.0&q=80&w=400', 'massa folhada');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('bolo-frap-e', '= Bolo frapê  =', 'Paes', '2009-11-23', 'Receita importada de 23_11_2009_Bolo_frape.doc', '[]', NULL, '= Bolo frapê  = Receita passa no dia 23/11/2009 ingredientes Farinha de trigo100%1500g Margarina31%465g Açúcar81%1215g Ovos47%705g Fermento em pó químico5%75g Biscomil5%75g Leite63%945g Chocolate em pó5%75g Amido de milho (biscomil)5%75g fimIngredientes ''''''Modo de preparo'''''' Coloque em uma batedeira 250 gramas de farinha margarina e açúcar e acrescentar o restante dos ovos e bater até cremar. Acrescentar farinha fermento e o amido deixando o leite por ultimo bata mais'''''' 5 minutos''''''. Separe 1/3 da massa acrescente o chocolate e misture a mão para obter um bolo do tipo frapê coloque sem chocolate em uma forma de pão de forma e o restante por cima e leve ao forno'''''' mais ou menos 20 minutos ''''''a uma ''''''temperatura de 180° graus''''''.', '', 'https://picsum.photos/seed/bolofrap/400/300', 'bolo frape');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('bolo-de-milho-verde', '= Bolo de milho verde =', 'Paes', '2009-11-16', 'Receita importada de 16_11_2009_Bolo_de_milho_verde.doc', '[]', NULL, 'Bata as claras separadamente após esse processo retire da batedeira de deixe descansar. ''''''Coloque na batedeira margarina e açúcar na terceira velocidade mais ou menos 5 minutos'''''' acrescente as gemas até obter um creme. Desligue a batedeira e acrescente com as mãos a farinha e o fubá e o fermento mexendo cuidadosamente para não deixar a massa dar liga. Acrescente o leite de coco e o milho e também as claras e misture com as mãos. Terminado esse processo coloque em formas para bolo Inglês untadas com manteiga e polvilhadas com farinha, e leve ao forno a uma temperatura ''''''180° graus'''''' mais ou menos ''''''25 minutos. ''''''', '', 'https://images.unsplash.com/photo-1603279126476-93ce8278312c?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8Ym9sbyUyMGRlJTIwbWlsaG8lMjB2ZXJkZXxlbnwwfHx8fDE3ODUxOTE0MTR8MA&ixlib=rb-4.1.0&q=80&w=400', 'bolo de milho verde');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('biscoito-areia-de-caiscais', '= Biscoito areia de caiscais =', 'Bolos', '2009-11-16', 'Receita importada de 16_11_2009_biscoito_areia_caiscais.doc', '[]', NULL, '= Biscoito areia de caiscais = receita passada no dia 16/11/2009 ingredientes Farinha de trigo100% Margarina67% Açúcar40% fimIngredientes ''''''Modo de preparo.'''''' Coloque farinha de trigo sobre a mesa e façauma cova e coloque o açúcar e a margarina misture com as mãos até ficar uma massa homogênea faça bolas de 1 centímetro de diametro arrume em tabuleiro levemente untada com óleo, leve ao forno por mais ou menos 15 minutos a uma temperatura 160 graus.', '', 'https://picsum.photos/seed/biscoitoareiadecaiscais/400/300', 'biscoito areia de caiscais');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('biscoito-de-champanhe', '= Biscoito de champanhe  =', 'Paes', '2009-11-16', 'Receita importada de 16_11_2009_biscoito_de_champanhe.doc', '[]', NULL, '= Biscoito de champanhe  = Receita passada no dia16/11/2009 ''''''Ingredientes'''''' ''''''ingredientes'''''' Farinha de trigo 100%1000 g Ovos50%500g Açúcar80%800g fimIngredientes ''''''Modo de preparo'''''' Coloque na ''''''batedeira'''''' açúcar e Ovos e deixe bater mais ou menos ''''''15 minutos'''''' na 3ª velocidade desligue a batedeira e vá acrescentando a farinha e mexer com mão. Coloque a massa em forma de biscoito de champanhe previamente untada com margarina e polvilhada com farinha,coloque açúcar cristal em cima dos biscoitos antes de assar, e leve ao forno por mais ou menos'''''' 8 minutos'''''' a uma temperatura de ''''''200º graus''''''', '', 'https://images.unsplash.com/photo-1613477581402-306fa9dc6b95?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8YmlzY29pdG8lMjBkZSUyMGNoYW1wYW5oZXxlbnwwfHx8fDE3ODUxOTE0MTV8MA&ixlib=rb-4.1.0&q=80&w=400', 'biscoito de champanhe');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('p-ao-de-queijo', '= Pão de queijo  =', 'Bolos', '2009-11-16', 'Receita importada de 16_11_2009_pao_de_queijo.doc', '[]', NULL, 'Juntar em uma bacia queijo e o sal e misture e junte os ovos e amasse muito bem depois acrescente o polvilho e fécula e ''''''amasse mais até ficar no ponto semelhante ao da coxinha''''''. Faça bolas e empane os pães em queijo parmesão ralado e arrume em uma levemente untada com óleo e leve ao forno mais ou menos ''''''20 minutos'''''' a uma temperatura de'''''' 290 Graus.''''''', '', 'https://images.unsplash.com/photo-1559141680-d0bd7bc5af84?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8cGFvJTIwZGUlMjBxdWVpam98ZW58MHx8fHwxNzg1MTkxNDE3fDA&ixlib=rb-4.1.0&q=80&w=400', 'pao de queijo');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('carinhoso', '= Carinhoso =', 'Massas', '2009-11-16', 'Receita importada de 16_11_2009_carinhoso.doc', '[]', NULL, '= Carinhoso = Receita passada no dia 16/11/2009 ''''''ingredientes'''''' ingredientes Amido de milho100%1000 g Margarina100%1000g Farinha de trigo70%700g Açúcar50%500g coco ralado30%300g fimIngredientes caso necessário Leite de coco20%200g ''''''Modo de preparo'''''' Sobre um mesa misture o amido com farinha abra uma cova e coloque açúcar e margaria amasse a obter uma lisa (caso necessário coloque o leite de coco para não deixar a massa seca) divida a massa com um cortador redondo e arrume a massa já modelada em uma bandeja e leve ao forno por mais ou menos 15 minutos a uma temperatura de 180 graus.', '', 'https://images.unsplash.com/photo-1651822841710-3b7f17ed0d34?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8Y2FyaW5ob3NvfGVufDB8fHx8MTc4NTE5MTQxNnww&ixlib=rb-4.1.0&q=80&w=400', 'carinhoso');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('p-ao-de-batata', '= Pão de batata =', 'Bolos', '2009-11-12', 'Receita importada de 12_11_2009_pao_de_batata.doc', '[]', NULL, 'Coloque ''''''1 quilo e meio de farinha'''''' ''''''com todo o fermento da receita'''''' na masseira e faça uma esponja e ''''''deixe descansar por 20 minutos'''''' coberta com plástico. Depois passe a batata já cozida no espremedor e coloque na masseira junto com o restante dos ingredientes depois junte as duas massas e amasse até obter uma massa enxuta e lisa e ''''''deixe descansar mais 20 minutos'''''' Obs.:'''''' Divida a massa em pedaços de 2 quilos'''''' para facilitar o manuseio e depois ''''''divida novamente em pedaços de 50 gramas'''''', recheie, faça bolas e arrume em uma bandeja untada levemente com óleo sobre o regime de arrumação de ''''''6 fileiras e 5 colunas'''''', deixe descansar em um armário ou coberto por um pano ou saco mais ou menos 9''''''0 minutos'''''', pinte com gema de ovo com meio crescimento, depois leve ao forno por ''''''mais ou menos 20 minutos'''''' a uma temperatura de'''''' 180 graus''''''.', '', 'https://images.unsplash.com/photo-1598142982901-df6cec10ae35?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8cGFvJTIwZGUlMjBiYXRhdGF8ZW58MHx8fHwxNzg1MTkxNDEzfDA&ixlib=rb-4.1.0&q=80&w=400', 'pao de batata');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('maria-mole', '= Maria mole =', 'Outros', '2009-11-11', 'Receita importada de 11_11_2009_maria_mole.doc', '[]', NULL, '= Maria mole = receita passada no dia 11/11/2009 _________________________________________________ ingredientes Açúcar100%1000g Gelatina neutra5%50g Água50%500g Coco ralado40%400g margarinaQBQB fimIngredientes === Modo de preparo === Hidrate a gelatina com a água da receita aquecendo no fogo, coloque na batedeira ainda quente a gelatina hidratada e o açúcar e ''''''deixe bater'''''' ''''''mais ou menos 20 minutos'''''' ou até que o creme não caia da colher. Coloque a creme em saco ou manga de confeitar com bico frisado de numero 8B, e estando a mesa previamente untada com a margarina, ''''''estenda o creme em pedaços de mais ou menos 7 centímetros ''''''de ''''''deixe secar mais ou menos 1 hora'''''' e passe as marias moles no coco ralado.', '', 'https://images.unsplash.com/photo-1645703697898-67ea1e0e11ec?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8bWFyaWElMjBtb2xlfGVufDB8fHx8MTc4NTE3NTg3Mnww&ixlib=rb-4.1.0&q=80&w=400', 'maria mole');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('p-ao-doce', '= Pão doce  =', 'Massas', '2009-11-09', 'Receita importada de 09_11_2009_pao_doce.doc', '[]', NULL, '= Pão doce  = Receita passada no dia 09/11/2009 ingredientes Farinha de trigo100%5000g Açúcar20% 1000g Sal2%100g Reforçador1%50g Margarina8%400g Ovos6%300g Fermento6%300g Água50%2500g fimIngredientes ''''''Modo de preparo'''''' Coloque todos os ingredientes secos na masseira e deixe bater 1 minutos, em seguida coloque a água e deixa bater 5 minutos. Após bater coloque a massa sobre uma mesa untada com óleo e corte em pedaços de 2 quilos e passe na cortadora para pães pequenos em corte em pedaços de 300 gramas para diversos. Modele e arrume em bandeja levemente untada com óleo sobre o regime de arrumação 10 por 3 caso os pães sejam pequenos, pinte os pães com gema de ovo e ''''''leve ao armário e deixe descansar por mais ou menos 120 minutos'''''' ou até dobrar de tamanho, antes de levar ao forno coloque recheio externo e abertura,'''''' leve para o forno por mais ou menos 20 minutos'''''' a uma'''''' temperatura de 160 graus''''''. Receita complementar ===== Creme para pão doce  ===== ingredientes Leite100%500g Farinha40%200g Açúcar___________________ CoranteQBQB fimIngredientes ''''''Modo de preparo '''''' Leve ao fogo 500 gramas de Leite e 200 gramas de açúcar uma pitada de corante deixar ferver. Reserve 200 gramas de farinha e 200 gramas de açúcar e misture vigorosamente quando o leite começar a ferver para não empelotar.', '', 'https://images.unsplash.com/photo-1580745605349-4f50567c1729?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8cGFvJTIwZG9jZXxlbnwwfHx8fDE3ODUxODg3MjB8MA&ixlib=rb-4.1.0&q=80&w=400', 'pao doce');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('minuta-de-chocolate', '= Minuta de chocolate  =', 'Paes', '2009-11-09', 'Receita importada de 09_11_2009_minuta_de_chocolate.doc', '[]', NULL, '= Minuta de chocolate  = Receita Passada no dia 09/11/2009 ingredientes Farinha de trigo 100 %1000g Açúcar35%350g Margarina 30%300g Ovos25%250g Fermento em pó químico5%50g Chocolate em pó20%200 g fimIngredientes ''''''Modo de preparo'''''' Bata o açúcar com a margarina até formar um creme e em seguida coloque a farinha, o chocolate, o fermento todos misturados deixando por ultimo os ovos para dar ponto cortar pedaços de 30 gramas e faça bolas e passe no açúcar cristalizado e Observação.:''''''leve ao forno por mais ou menos 20 minutos'''''' a uma ''''''temperatura de 180 graus''''''.', '', 'https://images.unsplash.com/photo-1610450949065-1f2841536c88?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8bWludXRhJTIwZGUlMjBjaG9jb2xhdGV8ZW58MHx8fHwxNzg1MTkxNDEyfDA&ixlib=rb-4.1.0&q=80&w=400', 'minuta de chocolate');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('brevidade', 'Brevidade', 'Massas', '2009-11-05', 'Receita importada de brevidade_05_11_2009.doc', '[]', NULL, 'coloque em uma bacia todos os ingredientes deixando o leite por ultimo para estabelecer o ponto adequado da massa, Bata a vá adicionando o leite até ela chegar no ponto, e em seguida use um saco ou manga de confeitar com bico liso ou frisado para arrumar a massa em um tabuleiro levemente untado com óleo, após ter terminado todos os processos anteriores leve a massa ao forno mais ou menos 20 minutos a uma temperatura de 180 graus.', '', 'https://images.unsplash.com/photo-1717070399018-238e78f93b3b?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8YnJldmlkYWRlfGVufDB8fHx8MTc4NTE5MTQzN3ww&ixlib=rb-4.1.0&q=80&w=400', 'brevidade');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('biscoito-amanteigado', '= Biscoito amanteigado =', 'Massas', '2009-11-04', 'Receita importada de biscoito_amanteigado_04_11_2009.doc', '[]', NULL, '# coloque na batedeira açúcar e margarina ''''''deixe bater 15 minutos ''''''ou até cremar . # Diminua a velocidade da batedeira e coloque os ovos e deixe bater por 3 minutos. # Depois desligue a batedeira coloque o restante dos ingredientes e deixe dar liga. # Após ponha a massa em um ''''''saco de confeitar com bico 8B,'''''' e arrume em bandeja levemente untada com óleo. # Leve ao forno por mais ou menos ''''''10 minutos ''''''a uma'''''' temperatura'''''' de ''''''180º''''''. <div style="margin-left:0cm;margin-right:0cm;"></div>', '', 'https://picsum.photos/seed/biscoitoamanteigado/400/300', 'biscoito amanteigado');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('rocambole', '= Rocambole =', 'Outros', '2009-11-04', 'Receita importada de rocambole_04_11_2009.doc', '[]', NULL, '# Coloque em uma batedeira os ovos e o açúcar e deixe bater por'''''' 15 mintos'''''' na 3ª velocidade. # Desligue a batedeira e coloque o restante dos ingedientes* e bata com as mão vigorosamente. # Coloque em uma mesa e espalhe em papel manteiga. # leve ao forno por mais ou menos ''''''5 minutos a uma temperatura de 180''''''°.', '', 'https://images.unsplash.com/photo-1641199790968-15b5a5486e46?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8cm9jYW1ib2xlfGVufDB8fHx8MTc4NTE5MTQ0Mnww&ixlib=rb-4.1.0&q=80&w=400', 'rocambole');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('broa-aerosa', '= Broa aerosa =', 'Paes', '2009-11-04', 'Receita importada de broa_aerosa_04_11_2009.doc', '[]', NULL, '# <div style="margin-left:1.27cm;margin-right:0cm;">Coloque para ferver o leite, margarina sal e o Açúcar e a erva doce.</div> # <div style="margin-left:1.27cm;margin-right:0cm;">Misture a farinha de trigo com fubá na bacia da batedeira a parte.</div> # <div style="margin-left:1.27cm;margin-right:0cm;">Quando ferver o leite misture com os ingredientes que estão na bacia e deixe bater trinta segundos.</div> # <div style="margin-left:1.27cm;margin-right:0cm;">desligue a batedeira coloque os ovos e deixe bater por mais 5 minutos ou até formar uma massa homogênea. </div> # <div style="margin-left:1.27cm;margin-right:0cm;">Deligue a batedeira e com a colher ou saco de confeitar, faça bolas de 30 gramas passe no fubá e arrume em bandeja untada com óleo.</div> # <div style="margin-left:1.27cm;margin-right:0cm;">Leve ao forno por mais ou menos 20 minutos a uma temperatura 180°</div>', '', 'https://picsum.photos/seed/broaaerosa/400/300', 'broa aerosa');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('bolo-ingl-es', '= Bolo Inglês  =', 'Paes', '2009-11-03', 'Receita importada de bolo_ingles_03_11_2009.doc', '[]', NULL, '# Coloque em uma batedeira na terceira velocidade margarina e açúcar por mais ou menos ''''''15 minutos'''''' ou até cremar # reduza a velocidade da batedeira para primeira, e coloque o restante dos ingredientes deixando o leite por ultimo . # Após os ingredientes misturados deixe bater por mais ''''''5 minutos''''''. # Tendo a massa atingido o ponto coloque em forma para bolo Inglês. # Asse no forno a ''''''180°'''''' por mais ou menos ''''''15 minutos.''''''', '', 'https://picsum.photos/seed/boloingls/400/300', 'bolo ingles');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('sequilho-de-coco', '= Sequilho de coco =', 'Bolos', '2009-11-03', 'Receita importada de sequilho_de_coco_03_11_2009.doc', '[]', NULL, '= Sequilho de coco = Receita passada no dia 03/11/2009 ingredientes Farinha de trigo70% Amido de milho100% Açúcar50% Margarina100% Coco ralado30% Leite de cocoQB fimIngredientes ''''''Modo de preparo'''''' # ## ### <div style="margin-left:2.54cm;margin-right:0cm;">junte a farinha de trigo, amido de milho e açúcar em uma bacia ou na mesa e misture bem com as mão</div> ### <div style="margin-left:2.54cm;margin-right:0cm;">Depois coloque a margarina e o coco ralado e continue misturando com mãos até ficar lisa e homogênea.</div> ### <div style="margin-left:2.54cm;margin-right:0cm;">Faça bolas pequenas e arrume em bandejas sobre o regime de arrumação e marque os biscoitos com um garfo .</div> ### <div style="margin-left:2.54cm;margin-right:0cm;">Leve ao forno a ''''''180° (cento e oitenta gráus)'''''' mais ou menos ''''''15 minutos'''''' .</div> Obs : Caso necessário use leite de coco para dar ponto.', '', 'https://images.unsplash.com/photo-1560769680-ba2f3767c785?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8c2VxdWlsaG8lMjBkZSUyMGNvY298ZW58MHx8fHwxNzg1MTkxNDQyfDA&ixlib=rb-4.1.0&q=80&w=400', 'sequilho de coco');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('p-ao-franc-es', '= Pão francês  =', 'Paes', '2009-10-29', 'Receita importada de pao_frances_29_10_2009.doc', '[]', NULL, '= Pão francês  = Receita passada na seguinte data 29/10/2009 ingredientes Farinha100% Sal2% Reforçador1% Fermento3% Água53% fimIngredientes ''''''Modo de preparo '''''' Coloque na masseira todos os ingredientes secos deixe bater por 2 minuto, após bater coloque o restante dos ingredientes de deixe bater mais 5 minutos ou até ficar lisa e homogênea, depois de bater coloque a massa em uma mesa untada com óleo e corte em pedaços de 2 quilos, após corte e modele a massa para por nas formas para pão francês (Grades) com as costuras voltadas para baixo e deixe descansar por mais ou menos 120 minutos, após o tempo adequado de descanso leve ao forno por mais ou menos 15 minutos com vapor . OBS: Para uma Boa aparência do Pão Filete com gilete antes de levar ao fono.', '', 'https://images.unsplash.com/photo-1585944285854-d06c019aaca3?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8cGFvJTIwZnJhbmNlc3xlbnwwfHx8fDE3ODUxOTE0NDB8MA&ixlib=rb-4.1.0&q=80&w=400', 'pao frances');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('pao-frances', 'Pao Frances', 'Paes', '2009-10-29', 'Receita de pao frances passada em sala de aula.', '{"sal":"2%","agua":"53%","farinha":"100%","fermento":"3%","reforcador":"1%"}', NULL, 'Coloque na masseira todos os ingredientes secos deixe bater por 2 minutos, apos bater coloque o restante dos ingredientes e deixe bater mais 5 minutos ou ate ficar lisa e homogenea, depois de bater coloque a massa em uma mesa untada com oleo e corte em pedacos de 2 quilos, apos corte e modele a massa para por nas formas para pao frances (graves) com as costuras voltadas para baixo e deixe descansar por mais ou menos 120 minutos, apos o tempo adequado de descanso leve ao forno por mais ou menos 15 minutos com vapor.', 'Para uma boa aparencia do pao filete com gilete antes de levar ao forno.', 'https://images.unsplash.com/photo-1599819055803-717bba43890f?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixlib=rb-4.1.0&q=80&w=400', 'pao frances');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('massa-pizza', 'Massa para Pizza', 'Massas', '2009-10-29', 'Receita de massa para pizza passada em sala de aula.', '{"sal":"2%","agua":"58%","ovos":"2%","acucar":"2%","farinha":"100%","fermento":"3%","margarina":"3%"}', NULL, 'Coloque todos os ingredientes secos na masseira e deixe bater por 1 minuto, depois de bater coloque o restante dos ingredientes e deixe bater novamente por mais 5 minutos ou ate a massa ficar lisa e homogenea, estando a massa lisa e homogenea retire da masseira e coloque sobre uma mesa levemente untada com oleo e corte em pedacos de acordo com a bandeja que sera usada para levar a massa ao forno, modele e fure com um garfo, e deixe descansar por mais ou menos 90 minutos, apos descansar leve ao forno por 4 minutos a uma temperatura de 180 graus, retire embale e guarde.', NULL, 'https://images.unsplash.com/photo-1537734796389-e1fc293cf856?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixlib=rb-4.1.0&q=80&w=400', 'massa para pizza');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('massa-para-pizza', '= Massa para pizza =', 'Massas', '2009-10-29', 'Receita importada de Maasa_para_pizza_29_10_2009.doc', '[]', NULL, '= Massa para pizza = receita passada na seguinte data 29/10/2009 ingredientes Farinha100% Sal2% Açúcar2% Margarina3% Fermento3% Ovos2% Água58% fimIngredientes ''''''Modo de preparo'''''' Coloque todos os ingredientes secos na masseira e deixe bater por 1 minuto depois de bater coloque o restante dos ingredientes de deixe bater novamente por mais 5 minutos ou até a massa ficar lisa e homogênea, estando a massa lisa e homogênea retire da masseira e coloque sobre uma mesa levemente untada com óleo e corte em pedaços de acordo com a bandeja que será usada para levar a massa ao forno, modele e fure com um garfo , e deixe descansar por mais ou menos 90 minutos, após descansar leve ao forno por 4 minutos a uma temperatura de 180 graus retire embale e guarde.', '', 'https://images.unsplash.com/photo-1537734796389-e1fc293cf856?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8bWFzc2ElMjBwYXJhJTIwcGl6emF8ZW58MHx8fHwxNzg1MTkxNDI3fDA&ixlib=rb-4.1.0&q=80&w=400', 'massa para pizza');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('pao-suico', 'Pao Suico', 'Paes', '2009-10-28', 'Receita de pao suico passada em sala de aula.', '{"sal":"2%","agua":"54%","ovos":"8%","acucar":"10%","farinha":"100%","fermento":"6%","margarina":"6%","reforcador":"1%"}', NULL, 'Coloque todos os ingredientes secos na masseira e deixe bater por um minuto, depois de bater coloque o restante dos ingredientes e deixe bater por mais 5 minutos ou ate ficar lisa e homogenea. Terminado este processo coloque a massa em uma mesa untada com oleo e divida em pedacos de dois quilos e depois divida a massa novamente em 30 pedacos, modele e arrume em uma bandeja sobre o regime 10 por 3 (3 colunas e 10 fileiras), ja arrumado deixe descansar em um armario, ou coberto com um pano ou saco plastico por mais ou menos 120 minutos. Apos descansar leve ao forno mais ou menos 20 minutos a uma temperatura de 180 graus.', 'Pinte com gema de ovo a meio crescimento.', 'https://images.unsplash.com/photo-1643369176535-139e9722209c?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixlib=rb-4.1.0&q=80&w=400', 'pao suico');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('p-ao-su-ico', '= Pão suíço  =', 'Massas', '2009-10-28', 'Receita importada de pao_suico_28_10_2009.doc', '[]', NULL, '= Pão suíço  = Receita passada na data 28/10/2009 ingredientes Farinha 100% Sal2% Açúcar10% Reforçador1% Fermento6% Margarina6% Ovos8% Água54% fimIngredientes === Modo de Preparo === Coloque Todos os ingredientes ''''''secos'''''' na masseira e deixe bater por um minuto, depois de bater coloque o restante dos ingredientes e deixe bater por mais 5 minutos ou até ficar lisa e homogênea. Terminado este processo coloque a massa em uma mesa untada com óleo e divida em pedaços de dois quilos e depois divida a massa novamente em 30 pedaços, modele e arrume em uma bandeja sobre o regime 10 por 3 (3 colunas e 10 fileiras), já arrumado deixe descansar em um armário, Ou coberto com um pano ou saco plástico por mais ou menos 120 minutos. Após descansar leve ao forno mais ou menos 20 minutos a uma temperatura de 180 graus, OBS: Pinte com gema de Ovo a meio crescimento.', '', 'https://images.unsplash.com/photo-1755880040137-565549850ccf?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8cGFvJTIwc3VpY298ZW58MHx8fHwxNzg1MTkxNDQxfDA&ixlib=rb-4.1.0&q=80&w=400', 'pao suico');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('bolo-m-ae-benta', '= Bolo mãe Benta =', 'Paes', '2009-10-27', 'Receita importada de bolo_mae_benta_27_10_2009.doc', '[]', NULL, '= Bolo mãe Benta = receita passada no dia 27/10/2009 ingredientes Farinha <nowiki>=</nowiki>100% Açúcar<nowiki>=</nowiki>75% Margarina<nowiki>=</nowiki>35% Fermento em pó<nowiki>=</nowiki>5% Ovos<nowiki>=</nowiki>60% Leite liquido<nowiki>=</nowiki>50% fimIngredientes Coloque em uma batedeira a margarina e açúcar, e deixe bater mais ou menos 15 minutos ou até a massa fique com um aspecto de creme, diminua a velocidade da batedeira coloque o restante dos ingredientes deixando o leite por último , após este processo aumente a velocidade da batedeira e deixe bater por mais 5 minutos. Estando a massa pronta use um saco de confeitar para colocar a massa em formas de papel de numero 0 (zero),depois leve ao forno por mais ou menos 15 minutos a uma temperatura de 180 graus.', '', 'https://images.unsplash.com/photo-1661200797308-604df94ec881?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8Ym9sbyUyMG1hZSUyMGJlbnRhfGVufDB8fHx8MTc4NTE5MTQzNnww&ixlib=rb-4.1.0&q=80&w=400', 'bolo mae benta');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('bolo-mae-benta', 'Bolo Mae Benta', 'Bolos', '2009-10-27', 'Receita de bolo mae benta passada em sala de aula.', '{"ovos":"60%","acucar":"75%","farinha":"100%","margarina":"35%","leite_liquido":"50%","fermento_em_po":"5%"}', NULL, 'Coloque em uma batedeira a margarina e acucar, e deixe bater mais ou menos 15 minutos ou ate a massa fique com um aspecto de creme, diminua a velocidade da batedeira coloque o restante dos ingredientes deixando o leite por ultimo, apos este processo aumente a velocidade da batedeira e deixe bater por mais 5 minutos. Estando a massa pronta use um saco de confeitar para colocar a massa em formas de papel de numero 0 (zero), depois leve ao forno por mais ou menos 15 minutos a uma temperatura de 180 graus.', NULL, 'https://images.unsplash.com/photo-1588195538326-c5b1e9f80a1b?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixlib=rb-4.1.0&q=80&w=400', 'bolo mae benta');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('broa-cachamb-u-cavaca', '= Broa cachambú (cavaca) =', 'Broas', '2009-10-22', 'Receita importada de Broa_cachambu_22_10_2009.doc', '[]', NULL, '= Broa cachambú (cavaca) = receita passada no dia 22/10/09 ingredientes Farinha <nowiki>= </nowiki>100% Fubá <nowiki>= </nowiki>100% Açúcar <nowiki>= </nowiki>100% Fermento em pó <nowiki>= </nowiki>5% Erva doce <nowiki>=</nowiki>5% Margarina <nowiki>= </nowiki>60% Ovos <nowiki>=</nowiki>30% fimIngredientes ''''''Modo de preparo'''''' Coloque todos os ingredientes em uma bacia, e misture até a massa ficar lisa e homogênea. Após arrume sobre o regime 9 por 6 (9 fileiras e seis colunas ) em uma bandeja levemente untada com óleo em porções de aproximadamente 30 gramas. Leve ao forno por 15 minutos a uma temperatura de 180 graus.', '', 'https://picsum.photos/seed/broacachambcavaca/400/300', 'broa cachambu cavaca');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('broa-cachambu', 'Broa Cachambu (Cavaca)', 'Broas', '2009-10-22', 'Receita de broa cachambu, tambem conhecida como cavaca.', '{"fuba":"100%","ovos":"30%","acucar":"100%","farinha":"100%","erva_doce":"5%","margarina":"60%","fermento_em_po":"5%"}', NULL, 'Coloque todos os ingredientes em uma bacia, e misture ate a massa ficar lisa e homogenea. Apos arrume sobre o regime 9 por 6 (9 fileiras e seis colunas) em uma bandeja levemente untada com oleo em porcoes de aproximadamente 30 gramas. Leve ao forno por 15 minutos a uma temperatura de 180 graus.', NULL, 'https://images.unsplash.com/photo-1582299385140-f316dbbba765?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixlib=rb-4.1.0&q=80&w=400', 'broa cachambu');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('brioche-industrial', '= Brioche industrial =', 'Paes', '2009-10-22', 'Receita importada de Brioche_industrial_22_10_2009.doc', '[]', NULL, '= Brioche industrial = ''''''receita passado no 22/10/2009'''''' ingredientes Farinha100% Reforçador1% Sal2% Açúcar2% Margarina6% Fermento6% Ovos6% Água54% fimIngredientes Coloque tos os ingredientes ''''''secos'''''' na masseira por 1 minuto ou até os ingredientes secos estiverem bem misturados,em seguida coloque o restante dos ingredientes e bater por mais 5 minutos ou até a massa ficar lisa e homogênea, em seguida coloque a massa em cima de uma mesa untada com óleo e divida a massa em pedaços de de 1,2 Kg (um quilo e duzentos gramas) , depois divida cada pedaço de 1,2Kg em trinta bolas e arrume as bolas em uma bandeja untada com óleo sobre o regime 6 por 5. Depois dessas etapas deixe a massa descansar um armário ou coberto com uma tampa ou pano. Após descansar a massa devidamente preparada leve ao forno pré aquecido aproximadamente por 10 minutos a uma temperatura de 180 graus.', '', 'https://picsum.photos/seed/briocheindustrial/400/300', 'brioche industrial');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('broa-de-milho', 'Broa de Milho', 'Broas', '2009-10-22', 'Receita de broa de milho passada em sala de aula.', '{"sal":"1,5%","agua":"+\/- 35%","fuba":"20%","ovos":"15%","acucar":"15%","farinha":"100%","fermento":"5% (ou 1\/3 se for fermento seco)","anti_mofo":"0,3%","erva_doce":"1,5%","margarina":"2,5%","reforcador":"1,5%"}', NULL, 'Coloque todos os ingredientes secos na masseira e deixe bater por um minuto, em seguida colocar o restante dos ingredientes e deixar bater aproximadamente 5 minutos, ou ate ficar lisa e homogenea. Apos bater divida a massa em dois pedacos de 2 quilos, depois divida esses pedacos em 30 partes. Estando as massas divididas faca bolas e passe na agua ou no fuba, arrume-as em bandejas sobre o regime 6 por 5 (cinco colunas e seis fileiras) levemente untadas com oleo, e deixe descansar por aproximadamente 120 minutos. Apos descansar leve ao forno por 20 minutos a uma temperatura de 180 graus.', NULL, 'https://images.unsplash.com/photo-1582299385140-f316dbbba765?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixlib=rb-4.1.0&q=80&w=400', 'broa de milho');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('pao-de-hamburguer', 'Pao de Hamburguer', 'Paes', '2009-10-20', 'Receita de pao de hamburguer passada em sala de aula.', '{"agua":"53%","ovos":"8%","acucar":"15%","farinha":"100%","fermento":"6% - se for seco use 1\/3","margarina":"8%","reforcador":"1%"}', NULL, 'Coloque todos os ingredientes secos na masseira, em seguida o restante, e deixe bater 5 minutos ou ate a massa ficar lisa. Retire a massa da masseira e coloque em uma mesa untada com oleo, em seguida divida a massa com um aparelho divisor em 30 pedacos, arrume sobre o regime 6 por 5 e deixe descansar no armario por aproximadamente 120 minutos ou ate dobrar de tamanho, apos descansar leve ao forno por 20 minutos a uma temperatura de 180 graus.', NULL, 'https://images.unsplash.com/photo-1508736793122-f516e3ba5569?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixlib=rb-4.1.0&q=80&w=400', 'pao de hamburguer');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('p-ao-de-hamb-urguer', '= Pão de hambúrguer  =', 'Massas', '2009-10-20', 'Receita importada de Pao_de_hamburguer_20_10_2009.doc', '[]', NULL, '= Pão de hambúrguer  = Receita passada no dia 20/10/2009 ''''''Ingredientes'''''' ingredientes Farinha100% Reforçador1% Açúcar15% Ovos8% Margarina8% Água53% Fermento6%(se o fermento for seco use 1/3 dessa quantidade) fimIngredientes ''''''Modo de preparo'''''' Coloque todos os ingredientes secos na masseira, em seguida o restante, e deixe bater 5 minutos ou até a massa ficar lisa. Retire a massa da masseira e coloque em uma mesa untada com óleo, em seguida divida a massa com um aparelho divisor em 30 pedaços,Arrume sobre o regime 6 por 5 e deixe descansar no armário pos aproximadamente 120 minutos ou até dobrar de tamanho, após descansar leve ao forno por 20 minutos a uma teperatura de 180 graus.', '', 'https://picsum.photos/seed/podehambrguer/400/300', 'pao de hamburguer');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('brioche-r-apido', '= Brioche rápido =', 'Paes', '2009-10-19', 'Receita importada de brioche_rapido_19_10_2009.doc', '[]', NULL, '= Brioche rápido = Receita passada no 19/10/2009 ''''''Esponja'''''' ingredientes total de farinha é igual 625 gramas Farinha 80%500g Fermento8%50g (se o fermento for seco use 1/3 dessa quantidade) Ovos8%50g Gema4,8%30g ÁguaQB(Quanto bastar) Açúcar12%75g sal1,6%10g margarina12%75% fimIngredientes ''''''Esponja de reforço'''''' ingredientes Farinha20%125g Ovos1(unidade)50g Gema1(Unidade)30g fimIngredientes ''''''Modo de preparo'''''' Caso o o fermento seja do tipo seco, comece misturando a farinha o o fermente antes de por a água, estando o fermento e a farinha bem misturadas, junte os outro ingredientes faça uma massa homogênea e deixe descansar por aproximadamente 30 minutos . Depois junte o restante da farinha, mais açúcar, sal e margarina, e faça uma massa homogênea, não esqueça da água! Misture a primeira massa com a segunda e abra massa com um rolo de pastel até ficar lisa e homogênea. Depois desse processo todo, enrole a massa como rocambole, e corte em pedaços de aproximadamente 30 gramas, arrume em um tabuleiro sobre o regime 9 por 6.Deixe descansar em um armário fechado ou coberto por um plástico por aproximadamente 90 minutos. Após descansar leve ao forno por 15 minutos na temperatura de 160 graus. Obs: Você pode colocar um recheio antes de enrolar com o rocambole !', '', 'https://picsum.photos/seed/briocherpido/400/300', 'brioche rapido');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('brioche-rapido', 'Brioche Rápido', 'Paes', '2009-10-19', 'Receita de brioche rapido passada em sala de aula.', '{"esponja":{"sal":"10g (1,6%)","agua":"QB (quanto basta)","gema":"30g (4,8%)","ovos":"50g (8%)","acucar":"75g (12%)","farinha":"500g (80%)","fermento":"50g (8%) - se for seco use 1\/3","margarina":"75g (12%)"},"esponja_reforco":{"gema":"1 unidade (30g)","ovos":"1 unidade (50g)","farinha":"125g (20%)"}}', '625g', 'Caso o fermento seja do tipo seco, comece misturando a farinha e o fermento antes de por a agua, estando o fermento e a farinha bem misturadas, junte os outros ingredientes, faca uma massa homogenea e deixe descansar por aproximadamente 30 minutos. Depois junte o restante da farinha, mais acucar, sal e margarina, e faca uma massa homogenea, nao esqueca da agua! Misture a primeira massa com a segunda e abra a massa com um rolo de pastel ate ficar lisa e homogenea. Depois desse processo todo, enrole a massa como rocambole, e corte em pedacos de aproximadamente 30 gramas, arrume em um tabuleiro sobre o regime 9 por 6. Deixe descansar em um armario fechado ou coberto por um plastico por aproximadamente 90 minutos. Apos descansar leve ao forno por 15 minutos na temperatura de 160 graus.', 'Voce pode colocar um recheio antes de enrolar como rocambole!', 'https://images.unsplash.com/photo-1552056413-b8b5eed0170b?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixlib=rb-4.1.0&q=80&w=400', 'brioche rapido');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('panetone', '= Panetone =', 'Paes', NULL, 'Receita importada de Sem_data_Panetone.doc', '[]', NULL, 'Misture a primeira massa com a segunda e bata até ficar lisa e homogênea, e depois misture as frutas ainda na masseira, e jogue toda massa em uma mesa untada com óleo, abra toda a massa e coloque as uvas passa no meio enrole como rocambole, e ''''''corte em pedaços de 520 gramas'''''' e ponha na forma e ''''''deixe descansar por 3 horas'''''' ou até encostar na borda da forma, e ''''''leve ao forno mais ou menos 40 minutos'''''' a uma ''''''temperatura de 180° graus''''''.', '', 'https://images.unsplash.com/photo-1481391145929-5bcf567d5211?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8cGFuZXRvbmV8ZW58MHx8fHwxNzg1MTkxNDI5fDA&ixlib=rb-4.1.0&q=80&w=400', 'panetone');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('massa-folhada-de-processo-alem-ao', '= Massa folhada (de processo Alemão) =', 'Massas', NULL, 'Receita importada de Sem_data_Massa_folhada_alema.doc', '[]', NULL, '= Massa folhada (de processo Alemão) = ingredientes Farinha de trigo100%1350g Água56%756g Margarina para massa Folhada74%999g Sal1%13,5g fimIngredientes ''''''Modo de preparo'''''' Coloque em uma masseira farinha sal e água e deixe bater até obter uma massa lisa e enxuta, e após deixe descansar mais ou menos 10 minutos. Depois corte a massa em cruz e abra as quatro pontas e coloque no centro a margarina folhada e cubra com a massa e dê uma volta de 3 e ''''''deixe descansar 20 minutos''''''. Dê mais duas voltas de 3 e ''''''deixe descansarmais 10 minutos'''''' e dê mais uma volta de três e ''''''deixe descansar mais 10 minutos'''''' e dê mais uma volta de 3 incompleta', '', 'https://images.unsplash.com/photo-1643941217351-27a8f0978bfc?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8bWFzc2ElMjBmb2xoYWRhJTIwZGUlMjBwcm9jZXNzbyUyMGFsZW1hb3xlbnwwfHx8fDE3ODUxOTE0Mjh8MA&ixlib=rb-4.1.0&q=80&w=400', 'massa folhada de processo alemao');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('bolo-m-armore', '= Bolo mármore  =', 'Paes', NULL, 'Receita importada de Sem_data_bolo_marmore.doc', '[]', NULL, '= Bolo mármore  = Receita do ano de 2009 ingredientes Farinha de trigo100%500g Margarina 100%500g Açúcar100%500g Ovos150%500g Fermento em pó químico5%25g Chocolate em pó10%50g fimIngredientes ''''''Modo de preparo'''''' Bata as claras separadamente retire do tacho e reserve. Junte a gema e o açúcar e acrescente a margarina aos poucos até obter uma massa lisa e homogênea. Acrescente a farinha e o fermento e misture com as mãos acrescente a claras e continue mexendo manualmente. Separe um 1/3 da massa acrescente o chocolate, depois coloque a primeiro a massa sem chocolate em uma forma de para pão de forma e e em seguida o restante e leve ao forno por ''''''mais ou menos 25 minutos'''''' a uma ''''''temperatura de 180° graus''''''.', '', 'https://picsum.photos/seed/bolomrmore/400/300', 'bolo marmore');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('p-ao-de-forma', '= Pão de forma  =', 'Paes', NULL, 'Receita importada de Sem_data_Pao_de_forma.doc', '[]', NULL, '= Pão de forma  = ingredientes Farinha de trigo100%5000g Água54%2700g Açúcar10%500g Fermento fresco6%300g Margarina 6300g Ovos 4%200g Sal2%100g Reforçador 1%50g fimIngredientes ''''''Modo de preparo'''''' Coloque na masseira todos os ingredientes secos de bater 1 minuto, depois coloque o restante dos ingredientes e deixe bater mais ou menos 5 minutos ou até a massa ficar lisa e homogênea. Retire a massa da masseira e coloque sobre uma mesa untada com óleo e ''''''corte em pedaços de 550 gramas'''''' modele e ponha em forma para pão de forma e deixe ''''''descansar mais ou menos 120 minutos'''''' ''''''ou até dois dedos para encostar na tampa'''''', e leve ao forno por ''''''mais ou menos 30 minutos'''''' a uma'''''' temperatura de 180 graus.''''''', '', 'https://images.unsplash.com/photo-1572105668569-62d3ae20fea8?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8cGFvJTIwZGUlMjBmb3JtYXxlbnwwfHx8fDE3ODUxOTE0MzB8MA&ixlib=rb-4.1.0&q=80&w=400', 'pao de forma');
INSERT INTO `receitas` (`id`, `titulo`, `categoria`, `data_receita`, `descricao`, `ingredientes`, `total_farinha`, `modo_preparo`, `observacoes`, `image_url`, `image_search_query`) VALUES ('biscoito-de-polvilho-azedo', '= Biscoito de polvilho azedo =', 'Doces', NULL, 'Receita importada de Sem_data_biscoito_de _polvilho_azedo.doc', '[]', NULL, 'Junte a primeira parte leve ao fogo fazendo um farofa e em seguida junte a primeira parte com a segunda parte em uma batedeira e deixe os ovos por ultimo para dar ponto. Retire da batedeira e coloque em um saco ou manga de confeitar, e com um bico frisado ou liso pingue em um tabuleiro e leve ao forno a uma ''''''temperatura de 200° mais ou menos 20 minutos ''''''.', '', 'https://images.unsplash.com/photo-1722239311715-90b2b89cfcbc?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDA4MjkyfDB8MXxzZWFyY2h8MXx8YmlzY29pdG8lMjBkZSUyMHBvbHZpbGhvJTIwYXplZG98ZW58MHx8fHwxNzg1MTkxNDMxfDA&ixlib=rb-4.1.0&q=80&w=400', 'biscoito de polvilho azedo');
